class KataTest {
    public static void main(String[] args) {
        bootcamp.Check.test("a transfer to an unknown account is refused and the source keeps its money", () -> {
            BankService bank = new BankService(java.util.List.of(), java.util.List.of());
            BankAccount a = bank.createAccount("Ada");
            bank.deposit(a.getId(), new java.math.BigDecimal("100.00"), null);
            bootcamp.Check.raises(IllegalArgumentException.class, () -> bank.transfer(a.getId(), "ACC-missing", new java.math.BigDecimal("30.00"), null));
            bootcamp.Check.eq(a.getBalance().toPlainString(), "100.00");
        });
        bootcamp.Check.test("a valid transfer logs both sides", () -> {
            BankService bank = new BankService(java.util.List.of(), java.util.List.of());
            BankAccount a = bank.createAccount("Ada");
            bank.deposit(a.getId(), new java.math.BigDecimal("100.00"), null);
            BankAccount b = bank.createAccount("Grace");
            bank.transfer(a.getId(), b.getId(), new java.math.BigDecimal("30.00"), null);
            bootcamp.Check.eq(bank.getTransactionsForAccount(b.getId()).size(), 1);
            bootcamp.Check.eq(b.getBalance().toPlainString(), "30.00");
        });
        System.exit(bootcamp.Check.report());
    }
}
// ─── end tests ───

